-- Reading B as stated: statin named on an undated legacy medication_lists snapshot row (no event_date).
SELECT COUNT(DISTINCT patient) AS count FROM records WHERE stream='medication_lists' AND json_extract(payload,'$.event_date') IS NULL AND (lower(json_extract(payload,'$.name')) LIKE '%simvastatin%' OR lower(json_extract(payload,'$.name')) LIKE '%atorvastatin%' OR lower(json_extract(payload,'$.name')) LIKE '%rosuvastatin%' OR lower(json_extract(payload,'$.name')) LIKE '%pravastatin%' OR lower(json_extract(payload,'$.name')) LIKE '%lovastatin%' OR lower(json_extract(payload,'$.name')) LIKE '%pitavastatin%' OR lower(json_extract(payload,'$.name')) LIKE '%fluvastatin%');
